def validate_manifest() -> None:
    """Validate the embedded installer manifest."""

    manifest = json.loads(FILES[".installer_manifest.json"])
    if manifest["module"] != "apps.patient_management.referrals":
        raise RuntimeError("Invalid Patient Referrals module.")
    if manifest["version"] != VERSION:
        raise RuntimeError("Installer version mismatch.")
    if manifest["canonical_patient"] != (
        "apps.patient_management.patients.models.Patient"
    ):
        raise RuntimeError("Canonical Patient reference is invalid.")
    if manifest["migration_policy"] != "no_migrations":
        raise RuntimeError("Migration policy must remain no_migrations.")
    if manifest["migrations_generated"] is not False:
        raise RuntimeError("Migrations must not be generated by this installer.")
    print("MANIFEST: PASS")


def validate_structure() -> None:
    """Validate the exact Patient Referrals source structure."""

    actual = set(FILES)
    expected = set(EXPECTED_FILES)
    missing = sorted(expected - actual)
    extra = sorted(actual - expected)
    if missing:
        raise RuntimeError("Required files missing:\n  " + "\n  ".join(missing))
    if extra:
        raise RuntimeError("Unexpected files embedded:\n  " + "\n  ".join(extra))
    print("STRUCTURE: PASS")


def validate_style() -> None:
    """Validate Python source conventions and syntax."""

    count = 0
    for relative_path, source in FILES.items():
        if not relative_path.endswith(".py"):
            continue
        tree = ast.parse(source, filename=relative_path)
        if not tree.body or not isinstance(tree.body[0], ast.Expr):
            raise RuntimeError(f"Missing module docstring: {relative_path}")
        if not any(
            isinstance(node, ast.ImportFrom)
            and node.module == "__future__"
            and any(alias.name == "annotations" for alias in node.names)
            for node in tree.body
        ):
            raise RuntimeError(f"Missing future annotations import: {relative_path}")
        count += 1

    for relative_path, source in FILES.items():
        if relative_path.endswith(".py") and "apps.clinical.patients.models" in source:
            raise RuntimeError(
                f"Legacy clinical Patient import detected: {relative_path}"
            )

    if "apps.patient_management.patients.models" not in FILES["models/referral.py"]:
        raise RuntimeError("Canonical Patient import is missing.")
    print(f"STYLE: PASS ({count} Python files)")


def validate_architecture() -> None:
    """Validate the production architecture boundaries."""

    required = (
        "models/referral.py",
        "managers.py",
        "selectors/referral.py",
        "services/referral.py",
        "policies/referral.py",
        "permissions/referral.py",
        "workflow_registry.py",
        "workflows/creation.py",
        "workflows/update.py",
        "workflows/deletion.py",
        "workflows/restore.py",
        "workflows/lifecycle.py",
        "events/referral_created.py",
        "events/referral_updated.py",
        "events/referral_deleted.py",
        "events/referral_restored.py",
        "events/referral_status_changed.py",
        "api/serializers/referral.py",
        "api/filters.py",
        "api/views/referral.py",
        "api/urls.py",
    )
    missing = [path for path in required if path not in FILES]
    if missing:
        raise RuntimeError("Architecture files missing: " + ", ".join(missing))

    registry = FILES["workflow_registry.py"]
    for workflow_name in (
        "patient_referral.create",
        "patient_referral.update",
        "patient_referral.delete",
        "patient_referral.restore",
        "patient_referral.lifecycle",
    ):
        if workflow_name not in registry:
            raise RuntimeError(f"Workflow registry missing: {workflow_name}")

    api_source = FILES["api/views/referral.py"]
    for workflow_class in (
        "ReferralCreationWorkflow",
        "ReferralUpdateWorkflow",
        "ReferralDeletionWorkflow",
        "ReferralRestoreWorkflow",
        "ReferralLifecycleWorkflow",
    ):
        if workflow_class not in api_source:
            raise RuntimeError(f"API workflow boundary missing: {workflow_class}")
    if "PatientReferralService" in api_source:
        raise RuntimeError("API must not call PatientReferralService directly.")
    if "PatientReferralFilter(" not in api_source:
        raise RuntimeError("Referral filter is not wired to the list API.")
    if api_source.count("HTTP_204_NO_CONTENT"):
        raise RuntimeError("DELETE endpoint must not return a body with HTTP 204.")

    service_source = FILES["services/referral.py"]
    if service_source.count("select_for_update()") < 4:
        raise RuntimeError("Referral mutations must lock rows for concurrency safety.")
    if "cannot be changed by referral update" not in service_source:
        raise RuntimeError("Protected referral fields must be rejected explicitly.")

    lifecycle_source = FILES["workflows/lifecycle.py"]
    if "select_for_update()" not in lifecycle_source:
        raise RuntimeError(
            "Lifecycle workflow must lock before capturing previous status."
        )

    restore_source = FILES["workflows/restore.py"]
    if "PatientReferral.all_objects" not in restore_source:
        raise RuntimeError(
            "Restore workflow must resolve deleted referrals from all_objects."
        )
    if "select_for_update()" not in restore_source:
        raise RuntimeError("Restore workflow must lock the deleted referral.")

    exception_source = FILES["exceptions.py"]
    if "patient_referral_duplicate_number" not in exception_source:
        raise RuntimeError("Duplicate referral failures must have a stable error code.")
    if "referral_failure_result" not in exception_source:
        raise RuntimeError(
            "Expected referral failures must be normalized at workflow boundary."
        )

    if "HTTP_409_CONFLICT" not in api_source:
        raise RuntimeError("Duplicate referral responses must use HTTP 409.")
    if "HTTP_500_INTERNAL_SERVER_ERROR" not in api_source:
        raise RuntimeError("Unexpected workflow failures must use HTTP 500.")

    if "PatientReferralPolicy.can_list(" not in api_source:
        raise RuntimeError("List API must enforce PatientReferralPolicy.can_list.")
    if (
        "except ObjectDoesNotExist:"
        not in api_source[api_source.index("class PatientReferralTransitionAPIView") :]
    ):
        raise RuntimeError("Transition API must map missing referrals to HTTP 404.")
    if "organization_roles" in api_source:
        raise RuntimeError(
            "API organization context must not fall back to the first role."
        )
    if "workflows/requests.py" in FILES:
        raise RuntimeError("Obsolete workflow request module must not be embedded.")

    serializer = FILES["api/serializers/referral.py"]
    for validator_name in (
        "validate_referral_number",
        "validate_referred_to",
        "validate_reason",
    ):
        if validator_name not in serializer:
            raise RuntimeError(f"Serializer validation missing: {validator_name}")

    print("ARCHITECTURE: PASS")


def validate_compile() -> None:
    """Compile every embedded Python source file."""

    count = 0
    for relative_path, source in FILES.items():
        if not relative_path.endswith(".py"):
            continue
        compile(source, relative_path, "exec")
        count += 1
    print(f"PY_COMPILE: PASS ({count} Python files)")


def install() -> None:
    """Perform a clean Patient Referrals installation."""

    validate_manifest()
    validate_structure()
    validate_style()
    validate_architecture()
    validate_compile()

    if TARGET.exists():
        shutil.rmtree(TARGET)
        print("OLD MODULE: DELETED")

    TARGET.mkdir(parents=True, exist_ok=True)
    for relative_path, source in FILES.items():
        destination = TARGET / relative_path
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(source, encoding="utf-8", newline="\n")

    print(f"FILES WRITTEN: {len(FILES)}")
    print("MIGRATIONS: NOT GENERATED")
    print("PATIENT REFERRALS INSTALLATION COMPLETE")


if __name__ == "__main__":
    install()
